import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './DescriptionList.module.css'

export interface DescriptionItem {
  term: string
  details: ReactNode
  /** An action for this row, e.g. an "Update" link. Shown at the row's end. */
  action?: ReactNode
  /** In the grid layout, take the full width: for long text or attachments. */
  isWide?: boolean
}

export interface DescriptionListProps extends Omit<ComponentProps<'section'>, 'title'> {
  items: DescriptionItem[]
  title?: ReactNode
  description?: ReactNode
  /** Buttons at the end of the header. */
  actions?: ReactNode
  /**
   * `columns`: term and details side by side, a row each.
   * `grid`: two columns of term-over-details pairs.
   * `stacked`: term over details, one after another. Columns fall back to
   * this on narrow screens anyway.
   */
  layout?: 'columns' | 'grid' | 'stacked'
  /** Put the list on a card with the header in its top band. */
  isCard?: boolean
  headingLevel?: 2 | 3
}

/**
 * The fields of a record as terms and details: a profile, an order, an
 * application. Read-only; its editable twin is a settings form.
 */
export function DescriptionList({
  items,
  title,
  description,
  actions,
  layout = 'columns',
  isCard = false,
  headingLevel = 2,
  className,
  ...props
}: DescriptionListProps) {
  const Heading = `h${headingLevel}` as const
  const hasHeader = title !== undefined || description !== undefined || actions !== undefined
  return (
    <section className={cn(styles.descriptionList, styles[layout], isCard && styles.card, className)} {...props}>
      {hasHeader && (
        <div className={styles.header}>
          <div className={styles.headerText}>
            {title && <Heading className={styles.title}>{title}</Heading>}
            {description && <p className={styles.description}>{description}</p>}
          </div>
          {actions && <div className={styles.actions}>{actions}</div>}
        </div>
      )}
      <dl className={styles.list}>
        {items.map((item) => (
          <div key={item.term} className={cn(styles.row, item.isWide && styles.wide, item.action !== undefined && styles.withAction)}>
            <dt className={styles.term}>{item.term}</dt>
            <dd className={styles.details}>{item.details}</dd>
            {item.action && <dd className={styles.action}>{item.action}</dd>}
          </div>
        ))}
      </dl>
    </section>
  )
}

.descriptionList {
  display: grid;
  gap: calc(var(--space-4) + var(--space-1));
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
  container-type: inline-size;
}

.header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4);
}

.headerText {
  display: grid;
  gap: var(--space-1);
  flex: 1 1 16rem;
}

.title {
  margin: 0;
  font-size: var(--text-heading-sm);
  line-height: var(--leading-heading-sm);
  font-weight: 600;
}

.description {
  margin: 0;
  color: var(--muted-foreground);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.list {
  display: grid;
  margin: 0;
}

.term {
  font-weight: 500;
}

.details {
  margin: 0;
  color: var(--muted-foreground);
  overflow-wrap: anywhere;
}

.action {
  margin: 0;
}

/* ------------------------------------------------------------- columns
   Term a third, details the rest, the action at the end; a line between
   rows. The columns belong to the list and every row is a subgrid of them,
   so details line up whether or not a row has an action. Below 36rem of
   the list's own width it stacks. */
.columns .list {
  grid-template-columns: minmax(0, 1fr);
}
.columns .row {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  gap: var(--space-1) var(--space-4);
  padding-block: var(--space-4);
  border-block-start: 1px solid var(--border);
}
.columns .row:last-child {
  border-block-end: 1px solid var(--border);
}
@container (min-width: 36rem) {
  .columns .list {
    grid-template-columns: minmax(0, 1fr) minmax(0, 2fr) auto;
    column-gap: var(--space-4);
  }
}

/* ---------------------------------------------------------------- grid */
.grid .list {
  grid-template-columns: 1fr;
  gap: var(--space-6) var(--space-4);
  padding-block-start: calc(var(--space-4) + var(--space-1));
  border-block-start: 1px solid var(--border);
}
@container (min-width: 36rem) {
  .grid .list {
    grid-template-columns: 1fr 1fr;
  }
}
.grid .row,
.stacked .row {
  display: grid;
  gap: var(--space-1);
  align-content: start;
}
.grid .wide {
  grid-column: 1 / -1;
}

/* ------------------------------------------------------------- stacked */
.stacked .list {
  gap: var(--space-4);
}

/* ---------------------------------------------------------------- card
   The header in a top band, the list below it, one border round both. */
.card {
  gap: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-panel);
  background: var(--card);
  color: var(--card-foreground);
  overflow: hidden;
}
.card > .header {
  padding: var(--space-4) var(--space-6);
  border-block-end: 1px solid var(--border);
}
.card > .list {
  padding: var(--space-6);
}
.card.columns > .list {
  padding-block: 0;
}
.card.columns .row:first-child {
  border-block-start: 0;
}
.card.columns .row:last-child {
  border-block-end: 0;
}
.card.grid > .list {
  border-block-start: 0;
}
